//! Cross-validation against **Sage** as an independent oracle.
//!
//! The fixture is generated by `scripts/gen_sage_oracle.sage` (committed, so
//! these tests need no Sage installed) and contains values Sage computed with
//! its own algorithms:
//!
//! * the classical layer — Kostka numbers as semistandard-tableau counts,
//!   symmetric group characters, Schur products (hence every LR coefficient),
//!   the four conversions out of the Schur basis, skew Schur functions and
//!   plethysms;
//! * Jack `P` and `J`, in the monomial and power-sum bases;
//! * the `(q,t)` layer — Hall–Littlewood `Q'` and `P`, Kostka–Foulkes, the
//!   `(q,t)`-Kostka table, `H̃`, `∇e_n`, and Macdonald `P`, `Q` and `J`;
//! * every **inverse** expansion — an element written back in a parametric
//!   basis rather than out of one: `s → P` and `s → Q'`, `s → H̃`, `s → J`,
//!   `m → P` and `m → Q`, and the three Jack ones. Sage reaches each by
//!   inverting or solving its own transition matrix where symfn
//!   back-substitutes through its own forward expansion, so agreement is what
//!   holds an inverse to something other than the expansion it came from —
//!   which the in-tree round trips cannot, being blind to any error the
//!   forward direction shares;
//! * the Kronecker product, and the three LLT ribbon dictionaries;
//! * the Hopf structure — coproduct, antipode and counit — and the two
//!   principal specializations with the dimension `f^λ`.
//!
//! Each family is the *offline* half of its oracle: the `scripts/check_*.py`
//! harnesses run wider, and these run on every `cargo test`. Where a family has
//! rival normalizations in circulation the fixture is chosen to tell them
//! apart, so it doubles as the convention pin — the `⚠️` notes below say which
//! swap each case would catch.
//!
//! Regenerate with:
//!   SAGE_DISABLE_SYMFN=1 sage scripts/gen_sage_oracle.sage > tests/fixtures/sage_oracle.txt
//!
//! ⚠️ The environment variable is not optional and the generator refuses
//! without it: Sage reaches this library through its optional backend, so a
//! fixture taken with it enabled is symfn quoting itself
//! (`docs/policies/validation.md`, V3).

use std::collections::BTreeMap;
use symfn::{
    antipode, character, coproduct, counit, dimension, hall_littlewood, hall_littlewood_p, kostka,
    kostka_foulkes, kronecker, macdonald_ht, nabla_e, principal_specialization,
    principal_specialization_q, qt_kostka, schur_to_hall_littlewood_p, schur_to_hall_littlewood_qp,
    skew_schur, Elementary, FromSchur, Homogeneous, Monomial, Partition, PowerSum, QtPoly,
    Rational, Ring, Schur, SymFn,
};

const FIXTURE: &str = include_str!("fixtures/sage_oracle.txt");

fn parse_partition(s: &str) -> Partition {
    if s.is_empty() {
        return Partition::default();
    }
    Partition::new(s.split(',').map(|x| x.parse::<u32>().expect("part")))
}

/// Parse `PART:COEFF ...` where COEFF is `n` or `n/d`.
fn parse_expansion(rest: &str) -> Vec<(Partition, (i128, i128))> {
    rest.split_whitespace()
        .map(|tok| {
            let (part, coeff) = tok.rsplit_once(':').expect("PART:COEFF");
            let c = match coeff.split_once('/') {
                Some((n, d)) => (n.parse().expect("num"), d.parse().expect("den")),
                None => (coeff.parse().expect("int"), 1),
            };
            (parse_partition(part), c)
        })
        .collect()
}

/// Iterate `(tag, arg, rest)` over fixture lines.
fn lines() -> impl Iterator<Item = (&'static str, &'static str, &'static str)> {
    FIXTURE.lines().filter(|l| !l.trim().is_empty()).map(|l| {
        let mut it = l.splitn(3, ' ');
        let tag = it.next().unwrap();
        let arg = it.next().unwrap_or("");
        let rest = it.next().unwrap_or("");
        (tag, arg, rest)
    })
}

fn pair(arg: &str) -> (Partition, Partition) {
    let (a, b) = arg.split_once('|').expect("LAM|MU");
    (parse_partition(a), parse_partition(b))
}

/// Compare an integral expansion against the oracle's expected terms.
fn assert_terms<S: SymFn<i64>>(actual: &S, expected: &[(Partition, (i128, i128))], what: &str) {
    let want: BTreeMap<Partition, i64> = expected
        .iter()
        .map(|(p, (n, d))| {
            assert_eq!(*d, 1, "{what}: expected integral coefficient");
            (p.clone(), *n as i64)
        })
        .collect();
    let got: BTreeMap<Partition, i64> = actual
        .terms()
        .iter()
        .map(|(p, c)| (p.clone(), *c))
        .collect();
    assert_eq!(got, want, "{what}");
}

#[test]
fn kostka_numbers_match_sage() {
    let mut n = 0;
    for (tag, arg, rest) in lines() {
        if tag != "kostka" {
            continue;
        }
        let (lam, mu) = pair(arg);
        let want: u128 = rest.trim().parse().expect("kostka value");
        assert_eq!(kostka(&lam, &mu), want, "K_{{{lam},{mu}}}");
        n += 1;
    }
    assert!(n > 100, "expected a real sweep, got {n}");
}

