#[test]
fn schur_products_match_sage() {
    let mut n = 0;
    for (tag, arg, rest) in lines() {
        if tag != "smul" {
            continue;
        }
        let (mu, nu) = pair(arg);
        let a: Schur<i64> = Schur::monomial(mu.clone(), 1);
        let b: Schur<i64> = Schur::monomial(nu.clone(), 1);
        assert_terms(&a.mul(&b), &parse_expansion(rest), &format!("s{mu}*s{nu}"));
        n += 1;
    }
    assert!(n > 50, "expected a real sweep, got {n}");
}

#[test]
fn integral_conversions_match_sage() {
    let mut n = 0;
    for (tag, arg, rest) in lines() {
        if !matches!(tag, "s2h" | "s2e" | "s2m") {
            continue;
        }
        let lam = parse_partition(arg);
        let s: Schur<i64> = Schur::monomial(lam.clone(), 1);
        let expected = parse_expansion(rest);
        match tag {
            "s2h" => assert_terms(
                &Homogeneous::from_schur(&s),
                &expected,
                &format!("h(s{lam})"),
            ),
            "s2e" => assert_terms(
                &Elementary::from_schur(&s),
                &expected,
                &format!("e(s{lam})"),
            ),
            "s2m" => assert_terms(&Monomial::from_schur(&s), &expected, &format!("m(s{lam})")),
            _ => continue,
        }
        n += 1;
    }
    assert!(n > 30, "expected a real sweep, got {n}");
}

#[test]
fn power_sum_conversion_matches_sage() {
    let mut n = 0;
    for (tag, arg, rest) in lines() {
        if tag != "s2p" {
            continue;
        }
        let lam = parse_partition(arg);
        let s: Schur<Rational> = Schur::monomial(lam.clone(), Rational::one());
        let got: PowerSum<Rational> = PowerSum::from_schur(&s);

        let want: BTreeMap<Partition, Rational> = parse_expansion(rest)
            .into_iter()
            .map(|(p, (num, den))| (p, Rational::new(num, den)))
            .collect();
        let actual: BTreeMap<Partition, Rational> =
            got.terms().iter().map(|(p, c)| (p.clone(), *c)).collect();
        assert_eq!(actual, want, "p(s{lam})");
        n += 1;
    }
    assert!(n > 10, "expected a real sweep, got {n}");
}

